-- fonte: Receita Federal (CNPJ), CNES, IBGE e OpenStreetMap
-- rode depois de tabela.sql, dados.sql e precos.sql (pode rodar mais de uma vez)

ALTER TABLE farmacia ADD COLUMN IF NOT EXISTS cidade VARCHAR(20);
ALTER TABLE farmacia ADD COLUMN IF NOT EXISTS tipo VARCHAR(10) NOT NULL DEFAULT 'privada';
ALTER TABLE farmacia ADD COLUMN IF NOT EXISTS cnpj VARCHAR(14);
ALTER TABLE farmacia ADD COLUMN IF NOT EXISTS precisao_posicao VARCHAR(30);
CREATE UNIQUE INDEX IF NOT EXISTS farmacia_cnpj_unico ON farmacia (cnpj);

ON CONFLICT (id) DO UPDATE SET
    nome = EXCLUDED.nome, endereco = EXCLUDED.endereco, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude,
    credenciada = EXCLUDED.credenciada, cidade = EXCLUDED.cidade, tipo = EXCLUDED.tipo, cnpj = EXCLUDED.cnpj,
    precisao_posicao = EXCLUDED.precisao_posicao;

-- só se ninguém usa a farmácia (estoque, habilitação, dispensação, agendamento ou preço)
